import type { ReactNode } from "react";

/**
 * The player's icon set ("Marker", set B chosen by the owner 2026-10-28): one hand-drawn 24x24 family of round-capped,
 * unfilled strokes that replaces lucide and the old custom glyphs in the player, its menus and the unmute hint.
 *
 * The component bodies below are generated from the design file (icon-sets/set-B.json) as plain JSX; do not edit the
 * path data by hand, regenerate it. Every icon is decorative (`aria-hidden`, `focusable=false`): the buttons that
 * hold them carry the accessible names. Colour comes from `currentColor`; the size on screen is set by CSS
 * (`.mc-icon` 20px, `.mc-hero-icon` 48px, `.mc-menu-check` 16px), so the 2.4 stroke of the 24px box renders as
 * 2px in the bar and 4.8px in the centre mark: one weight relative to the glyph, whatever the size.
 */
export type PlayerIconProps = {
  className?: string;
  testId?: string;
  /** Stroke width in the 24px box (default 2.4, the weight of the set). */
  strokeWidth?: number;
  "data-crossed"?: "true" | "false";
};

export const PLAYER_ICON_STROKE = 2.4;

/** Width of each pause bar in the 24px box (a solid bar, not the 2.4 line of the rest of the set). */
export const PAUSE_BAR_STROKE = 3.6;

function IconSvg({ className, testId, strokeWidth = PLAYER_ICON_STROKE, children, ...rest }: PlayerIconProps & { children: ReactNode }) {
  return (
    <svg
      viewBox="0 0 24 24"
      className={className}
      data-testid={testId}
      data-crossed={rest["data-crossed"]}
      aria-hidden="true"
      focusable="false"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {children}
    </svg>
  );
}

