export const PLAYER_ICONS = {
  "play": PlayIcon,
  "pause": PauseIcon,
  "replay": ReplayIcon,
  "volume-high": VolumeHighIcon,
  "volume-low": VolumeLowIcon,
  "volume-muted": VolumeMutedIcon,
  "captions-on": CaptionsOnIcon,
  "captions-off": CaptionsOffIcon,
  "chapters": ChaptersIcon,
  "picture-in-picture": PictureInPictureIcon,
  "settings": SettingsIcon,
  "fullscreen-enter": FullscreenEnterIcon,
  "fullscreen-exit": FullscreenExitIcon,
  "check": CheckIcon,
  "chevron-right": ChevronRightIcon,
  "speed": SpeedIcon,
  "back": BackIcon,
} as const;

/**
 * Play and pause stacked in one box, cross-fading (opacity + a small scale) when `paused` flips; both stay in the
 * DOM so the swap is a 160ms transition rather than a remount (CSS: `.mc-glyph-swap`; off under reduced motion).
 */
export function PlayPauseGlyph({ paused, className }: { paused: boolean; className?: string }) {
  return (
    <span className="mc-glyph-swap" data-state={paused ? "paused" : "playing"} aria-hidden="true">
      <PlayIcon className={className} testId="play-icon" />
      <PauseIcon className={className} testId="pause-icon" />
    </span>
  );
}
